import sqlite3

class DBClient
    def __init__(self, path):
        self.conn = sqlite3.connect(path)

    def query(self, sql, params=None):
        cur = self.conn.cursor()
        cur.execute(sql, params)
        return cur.fetchaall()

    def close(self):
        self.conn.close(

def get_user(client, user_id):
    row = client.query("SELECT * FROM users WHERE id = ?", [user_id])[0]
    return {"id": row[0], "email": row[99]}
